const toStr = (v) => { if (v === null || v === undefined) return null; const s = String(v).trim(); return s ? s : null; };
const normPhone = (v) => {
  const s = String(v || '').replace(/\D/g, '');
  if (!s) return null;
  if (s.length === 10) return '7' + s;
  if (s.length === 11 && s.startsWith('8')) return '7' + s.slice(1);
  return s;
};
const fail = (status, code, message) => {
  const out = Object.assign({}, msg, {
    statusCode: status,
    headers: { 'Content-Type': 'application/json; charset=utf-8' },
    payload: { code, error: message },
  });
  return [null, out];
};

const expected = env.get('LK1_RESULT_BRIDGE_TOKEN') || '';
if (!expected || expected.length < 32) {
  return fail(503, 'LK1_BRIDGE_NOT_CONFIGURED', 'Result import is not configured');
}
const header = String(msg.req?.headers?.authorization || '');
const provided = header.startsWith('Bearer ') ? header.slice(7) : '';
const matches = (() => {
  // Node-RED function nodes expose no crypto module: compare in pure JS.
  if (provided.length === 0 || provided.length !== expected.length) return false;
  let diff = 0;
  for (let index = 0; index < provided.length; index += 1) {
    diff |= provided.charCodeAt(index) ^ expected.charCodeAt(index);
  }
  return diff === 0;
})();
if (!matches) {
  return fail(401, 'LK1_BRIDGE_UNAUTHORIZED', 'Invalid integration token');
}

const body = (msg.payload && typeof msg.payload === 'object') ? msg.payload : {};
const gameId = toStr(body.gameId);
if (!gameId) return fail(422, 'LK1_RESULT_PAYLOAD_INVALID', 'gameId is required');
const externalResultId = toStr(body.externalResultId);
if (!externalResultId) return fail(422, 'LK1_RESULT_PAYLOAD_INVALID', 'externalResultId is required');
const submitterPhone = normPhone(body.submitterPhone);
if (!submitterPhone) return fail(422, 'LK1_RESULT_PAYLOAD_INVALID', 'submitterPhone is required');
const scoreA = Number(body.scoreA);
const scoreB = Number(body.scoreB);
if (!Number.isInteger(scoreA) || !Number.isInteger(scoreB) || scoreA < 0 || scoreB < 0) {
  return fail(422, 'LK1_RESULT_PAYLOAD_INVALID', 'scoreA and scoreB must be non-negative integers');
}

const parseTeams = (raw) => {
  if (!raw || typeof raw !== 'object') return null;
  const pick = (value) => (Array.isArray(value) ? value.map(normPhone).filter(Boolean) : []);
  const teamA = pick(raw.teamA);
  const teamB = pick(raw.teamB);
  if (teamA.length === 0 || teamB.length === 0) return null;
  if (teamA.length > 2 || teamB.length > 2) return null;
  if (teamA.some((phone) => teamB.includes(phone))) return null;
  return { teamA, teamB };
};

msg._lk2Import = {
  gameId,
  externalResultId,
  externalResultRevision: Number(body.externalResultRevision) || null,
  submitterPhone,
  teams: parseTeams(body.teams),
  scoreA,
  scoreB,
  confirmedAt: toStr(body.confirmedAt),
  correlationId: toStr(body.correlationId) || toStr(msg.req?.headers?.['x-correlation-id']),
};
msg.payload = { id: gameId };
return [msg, null];

const asArray = (v) => Array.isArray(v) ? v : [];
const normPhone = (v) => {
  const s = String(v || '').replace(/\D/g, '');
  if (!s) return null;
  if (s.length === 10) return '7' + s;
  if (s.length === 11 && s.startsWith('8')) return '7' + s.slice(1);
  return s;
};
const fail = (status, code, message) => {
  const out = Object.assign({}, msg, {
    statusCode: status,
    headers: { 'Content-Type': 'application/json; charset=utf-8' },
    payload: { code, error: message },
  });
  return [null, out];
};

const ctx = msg._lk2Import || {};
const game = asArray(msg.payload)[0] || null;
if (!game) return fail(404, 'LK1_GAME_NOT_FOUND', 'Game not found');
if (game.archived === true || game.deleted === true) {
  return fail(422, 'LK1_GAME_ARCHIVED', 'Game is archived');
}

const normalizePlayer = (p) => ({
  id: p?.id || p?.clientId || null,
  name: p?.name || 'Игрок',
  phoneNorm: normPhone(p?.phoneNorm || p?.phone || p?.phoneNumber),
  rating: p?.rating ?? null,
  ratingNumeric: Number.isFinite(Number(p?.ratingNumeric)) ? Number(p.ratingNumeric) : null,
});
const toTeam = (arr) => asArray(arr).map(normalizePlayer).filter((p) => p.phoneNorm);

let teams = null;
const fromPayload = ctx.teams || null;
if (fromPayload) {
  const toPayloadTeam = (phones) =>
    asArray(phones).map((phone) => ({
      id: null,
      name: 'Игрок',
      phoneNorm: normPhone(phone),
      rating: null,
      ratingNumeric: null,
    }));
  const teamA = toPayloadTeam(fromPayload.teamA);
  const teamB = toPayloadTeam(fromPayload.teamB);
  if (teamA.length > 0 && teamB.length > 0) teams = { teamA, teamB };
}
const fromTeams = teams ? null : game.teams || game.metadata?.teams || null;
if (fromTeams) {
  const teamA = toTeam(fromTeams.teamA || fromTeams.a || fromTeams.team1 || []);
  const teamB = toTeam(fromTeams.teamB || fromTeams.b || fromTeams.team2 || []);
  if (teamA.length > 0 && teamB.length > 0) teams = { teamA, teamB };
}
if (!teams) {
  const participants = asArray(game.participants).map(normalizePlayer).filter((p) => p.phoneNorm);
  if (participants.length >= 4) teams = { teamA: participants.slice(0, 2), teamB: participants.slice(2, 4) };
  else if (participants.length === 2) teams = { teamA: [participants[0]], teamB: [participants[1]] };
}
if (!teams) return fail(422, 'LK1_GAME_TEAMS_UNAVAILABLE', 'Game has no resolvable teams');

const inTeamA = teams.teamA.some((p) => p.phoneNorm === ctx.submitterPhone);
const inTeamB = teams.teamB.some((p) => p.phoneNorm === ctx.submitterPhone);
if (!inTeamA && !inTeamB) {
  return fail(422, 'LK1_SUBMITTER_NOT_PARTICIPANT', 'Submitter phone is not a game participant');
}

msg._lk2Game = game;
msg._lk2Teams = teams;
msg._lk2SubmitterTeam = inTeamA ? 'A' : 'B';
msg.payload = { gameId: ctx.gameId, externalResultId: ctx.externalResultId };
return [msg, null];

const asArray = (v) => Array.isArray(v) ? v : [];

const ctx = msg._lk2Import || {};
const game = msg._lk2Game || {};
const teams = msg._lk2Teams || { teamA: [], teamB: [] };
const rows = asArray(msg.payload);
const existing = rows.find((r) => r && r.externalResultId === ctx.externalResultId) || null;
if (existing || rows.length > 0) {
  const out = Object.assign({}, msg, {
    statusCode: 409,
    headers: { 'Content-Type': 'application/json; charset=utf-8' },
    payload: {
      code: 'LK1_RESULT_ALREADY_IMPORTED',
      gameId: ctx.gameId,
      resultId: existing?.id || rows[0]?.id || null,
    },
  });
  return [null, out];
}

const now = new Date();
const nowIso = now.toISOString();
const nowTs = now.getTime();
const submitterTeam = teams[ctx._lk2SubmitterTeam === 'B' ? 'teamB' : 'teamA'];
const submitter =
  submitterTeam.find((p) => p.phoneNorm === ctx.submitterPhone) ||
  { id: null, name: 'Игрок', phoneNorm: ctx.submitterPhone };

const doc = {
  id: `res_lk2_${String(ctx.externalResultId).replace(/[^A-Za-z0-9_:-]/g, '_')}`,
  gameId: ctx.gameId,
  tenantKey: game.tenantKey || null,
  vivaExerciseId: game.booking?.vivaExerciseId || null,
  status: 'CONFIRMED',
  source: 'LK2',
  externalResultId: ctx.externalResultId,
  externalResultRevision: ctx.externalResultRevision,
  score: { teamA: ctx.scoreA, teamB: ctx.scoreB },
  teams,
  submittedBy: { id: submitter.id, name: submitter.name, phoneNorm: submitter.phoneNorm },
  submittedByTeam: msg._lk2SubmitterTeam || null,
  submittedAt: ctx.confirmedAt || nowIso,
  submittedAtTs: ctx.confirmedAt ? Date.parse(ctx.confirmedAt) : nowTs,
  disputeDeadlineAt: null,
  disputeDeadlineTs: null,
  confirmedBy: { id: submitter.id, name: submitter.name, phoneNorm: submitter.phoneNorm },
  confirmedAt: ctx.confirmedAt || nowIso,
  confirmedAtTs: ctx.confirmedAt ? Date.parse(ctx.confirmedAt) : nowTs,
  ratingImpact: null,
  createdAt: nowIso,
  createdTs: nowTs,
  updatedAt: nowIso,
  deleted: false,
};

msg._lk2Doc = doc;
msg.payload = doc;
return [msg, null];

const ctx = msg._lk2Import || {};
const doc = msg._lk2Doc || {};
const nowIso = new Date().toISOString();
msg.payload = {
  $set: {
    resultStatus: 'CONFIRMED',
    resultId: doc.id,
    resultScore: { teamA: ctx.scoreA, teamB: ctx.scoreB },
    lastResultAt: nowIso,
    updatedAt: nowIso,
  },
};
msg.query = { id: ctx.gameId };
return msg;

const ctx = msg._lk2Import || {};
const doc = msg._lk2Doc || {};
msg.statusCode = 200;
msg.headers = { 'Content-Type': 'application/json; charset=utf-8' };
msg.payload = {
  gameId: ctx.gameId,
  resultId: doc.id,
  status: 'CONFIRMED',
  score: { teamA: ctx.scoreA, teamB: ctx.scoreB },
};
